const fs = require('fs');
const path = require('path');

const contextRoot = path.join(__dirname, '.agents', 'context');
const headerRegex = /^<!-- Context: .* -->/;
const markdownLinkRegex = /\[[^\]]*\]\(([^)]+)\)/g;

let error = false;
let fileCount = 0;

function rel(filePath) {
  return path.relative(path.join(__dirname, '.agents'), filePath).replace(/\\/g, '/');
}

// collect all .md files
function listMarkdown(dir) {
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .flatMap((entry) => {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) return listMarkdown(full);
      if (entry.name.endsWith('.md')) return [full];
      return [];
    });
}

const files = listMarkdown(contextRoot);

// 1. header comment on every file
for (const f of files) {
  fileCount++;
  const content = fs.readFileSync(f, 'utf8');
  const firstLine = content.split('\n')[0];
  if (!headerRegex.test(firstLine)) {
    error = true;
    console.error(`Missing header: ${rel(f)} — first line must be "<!-- Context: ... -->"`);
  }
}

// 2. every category dir has navigation.md
const categories = fs
  .readdirSync(contextRoot, { withFileTypes: true })
  .filter((e) => e.isDirectory());
for (const cat of categories) {
  const nav = path.join(contextRoot, cat.name, 'navigation.md');
  if (!fs.existsSync(nav)) {
    error = true;
    console.error(`Missing navigation.md in category: ${cat.name}`);
  }
}

// 3. relative markdown links in navigation.md resolve
for (const f of files) {
  if (!f.endsWith(path.sep + 'navigation.md')) {
    continue;
  }
  const content = fs.readFileSync(f, 'utf8');
  // skip links that are pure anchors or http(s)
  for (const match of content.matchAll(markdownLinkRegex)) {
    const link = match[1];
    if (/^(https?:|mailto:|#)/.test(link)) {
      continue;
    }
    const stripped = link.split('#')[0];
    if (!stripped) {
      continue;
    }
    const target = path.resolve(path.dirname(f), stripped);
    if (!fs.existsSync(target)) {
      error = true;
      console.error(`Broken link in ${rel(f)}: ${link} (→ ${rel(target)})`);
    }
  }
}

console.log(`Checked ${fileCount} markdown files in .agents/context`);
if (error) {
  console.error('context:validate FAILED');
  process.exit(1);
}
console.log('context:validate PASSED');
```

